"""
ClickUp task generator agent.

This module defines the ClickUpTaskFromSummaryGeneratorAgent, responsible for generating
ClickUp tasks from a meeting summary using an LLM. It transforms unstructured
meeting content into structured domain tasks compatible with ClickUp workflow.
"""

import logging
import json
from typing import List, Dict

from backend.src.domain.entities.generated_tasks.generated_task_from_summary import GeneratedTaskFromSummary
from backend.src.domain.entities.generated_tasks.generated_task_from_summary import GeneratedTaskListFromSummary
from backend.src.domain.ports.services.iprompt_loader import IPromptLoader
from backend.src.domain.ports.services.task_generation_from_summary.i_task_generator_from_summary import ITaskGeneratorFromSummary
from backend.src.infrastructure.external.shared.agents.base_agent import BaseAgent


logger = logging.getLogger(__name__)


class ClickUpTaskFromSummaryGeneratorAgent(BaseAgent[GeneratedTaskListFromSummary], ITaskGeneratorFromSummary):
    """
    LLM-based implementation of ITaskGenerator.

    This agent is responsible for:
    - Generating ClickUp tasks from a meeting summary
    - Mapping unstructured text into structured task entities
    - Aligning tasks with available folders, statuses, and priorities
    """

    def __init__(self, prompt_loader: IPromptLoader):
        """
        Initialize the ClickUpTaskFromSummaryGeneratorAgent.

        Args:
            prompt_loader (IPromptLoader): Service responsible for loading
                prompt templates used by the agent during LLM interactions.
        """
        super().__init__(prompt_loader)

    def generate_tasks(
        self,
        meeting_summary: str,
        locations_statuses: Dict[str, Dict[str, List[str]]]
    ) -> List[GeneratedTaskFromSummary]:
        """
        Generate ClickUp tasks from a meeting summary using an LLM.

        This method:
        - Sends the meeting summary and workspace structure to the LLM
        - Uses prompt templates to guide structured task generation
        - Parses the LLM response into domain task objects

        Args:
            meeting_summary: Meeting content in Arabic.
            locations_statuses: Mapping of locations to available statuses and priorities.

        Returns:
            List[GeneratedTaskFromSummary]: List of structured tasks generated by the LLM.

        Raises:
            LLMNetworkException: If a network error occurs while contacting the LLM.
            LLMApiException: If the LLM API returns an error response.
            LLMParsingException: If the LLM response cannot be parsed correctly.
        """
        logger.info("Starting task generation process from meeting summary.")

        # Convert the dictionary to JSON text to provide to the LLM
        if locations_statuses:
            locations_text = json.dumps(locations_statuses, ensure_ascii=False, indent=2)
        else:
            locations_text = "No locations available."

        parsed: GeneratedTaskListFromSummary = self._call_llm(
            agent_name="ClickUpTaskFromSummaryGeneratorAgent",
            folder_name="task_generation_from_summary",
            prompt_name="clickup_task_generator_agent",
            variables={
                "meeting_summary": meeting_summary,
                "locations_text": locations_text
            },
            response_format=GeneratedTaskListFromSummary,
        )

        if not parsed or not parsed.tasks:
            logger.warning("No tasks extracted from meeting summary.")
            return []

        logger.info(
            "Task generating from meeting summary completed successfully: %d task(s) generated.",
            len(parsed.tasks)
        )

        return parsed.tasks